// Builds the full week-over-week picture from saved history.
// Counting is done here in code, not by the AI model.
const rows = $input.all().map(i => i.json);

// One row per task per week (ignores duplicates from re-runs)
const seen = new Set();
const history = rows
  .filter(r => r.task_id && r.week)
  .filter(r => {
    const k = `${r.task_id}|${r.week}`;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });

const weeks = [...new Set(history.map(r => r.week))].sort();
const latest = weeks[weeks.length - 1];
const ids = [...new Set(history.map(r => r.task_id))].sort();

const tasks = ids.map(id => {
  const tl = history
    .filter(r => r.task_id === id)
    .sort((a, b) => String(a.week).localeCompare(String(b.week)));
  const last = tl[tl.length - 1];

  let streak = 0;
  const entries = [];
  for (let i = tl.length - 1; i >= 0; i--) {
    if (tl[i].status === last.status) { streak++; entries.unshift(tl[i]); }
    else break;
  }
  const sprints = [...new Set(entries.map(e => e.sprint))];
  const stuck =
    (last.status === 'Blocked' && streak >= 2) ||
    (last.status === 'In Progress' && streak >= 3);

  return {
    task_id: id,
    title: last.title,
    status: last.status,
    assignee: last.assignee || 'Unassigned',
    due_date: last.due_date,
    weeks_in_status: streak,
    sprints_spanned: sprints,
    stuck,
    stuck_over_one_sprint: stuck && sprints.length > 1,
    timeline: tl.map(t => `${t.week}: ${t.status}`).join(' | '),
  };
});

return [{
  json: {
    latest_week: latest,
    weeks_available: weeks,
    stuck_over_one_sprint: tasks.filter(t => t.stuck_over_one_sprint),
    stuck_any: tasks.filter(t => t.stuck),
    tasks,
  },
}];
